import torch
import torch.nn as nn
import avelang
import avelang.language as al


@avelang.jit
def reverse_cumsum_kernel(
    x_ptr: al.Pointer(al.bf16),
    out_ptr: al.Pointer(al.bf16),
    N: al.i32,
):
    row = al.block_id(0)
    tid = al.thread_id(0)

    layout_2d = al.make_layout((N, N), (N, 1))
    out = al.make_tensor(out_ptr, al.bf16, layout_2d)

    # Simplest possible shared memory test
    smem = al.make_shared((256,), al.f32)
    smem[tid] = al.convert(1.0, al.f32)
    al.syncthreads()

    # Thread 0 writes smem[0] to output, others write 0
    if tid == 0:
        out[row, 0] = al.convert(smem[0], al.bf16)
    else:
        out[row, tid] = al.convert(0.0, al.bf16)


def avelang_reverse_cumsum(x: torch.Tensor, dim: int) -> torch.Tensor:
    assert x.is_cuda, "Input must be on CUDA/HIP device."
    assert x.ndim == 2, "Input must be a 2D tensor."
    assert dim == 1, "Only dim=1 is supported."

    M, N = x.shape

    x_bf16 = x.to(torch.bfloat16).contiguous()
    out_bf16 = torch.empty_like(x_bf16)

    reverse_cumsum_kernel[lambda: ((M, 1, 1), (256, 1, 1))](
        x_bf16, out_bf16, N
    )

    return out_bf16.to(x.dtype)


class ModelNew(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.dim = dim

    def forward(self, x):
        return avelang_reverse_cumsum(x, self.dim)
